async function createReport(context: any, scope: any[]) {
    context.log("Running Analysis - Creating Report");

    if (!scope || scope.length === 0) {
        return context.log("No data in scope");
    }

    const reportData = extractReportData(scope);
    const device_id = scope[0].device;

    if (!reportData.report_device) {
        reportData.report_device = device_id;
    }

    if (!reportData.report_device || !reportData.report_send_to || !reportData.report_start_date || !reportData.report_end_date || !reportData.report_variables?.length) {
        return context.log("Missing report fields. Required: report_device, report_variables, report_start_date, report_end_date, report_send_to");
    }

    const startDate = parseDate(reportData.report_start_date);
    const endDate = parseDate(reportData.report_end_date, true);

    if (!startDate || !endDate || startDate > endDate) {
        return context.log(`Invalid report period. start=${reportData.report_start_date} end=${reportData.report_end_date}`);
    }

    const token = context.token;
    const resources = new Resources({ token });
    const services = new Services({ token });
    const recipient = await resolveRecipientEmail(resources, reportData.report_send_to);
    const extraEmail = parseOptionalExtraEmail(reportData.report_send_to_1);

    if (extraEmail.error) {
        await sendReportValidation(resources, device_id, extraEmail.error, "danger", reportData.report_session_id);
        return context.log(`Invalid extra report email. report_send_to_1=${reportData.report_send_to_1}`);
    }

    if (!recipient) {
        return context.log(`Invalid report recipient. report_send_to=${reportData.report_send_to}`);
    }

    const recipientEmails = Array.from(new Set([
        recipient.email,
        extraEmail.email
    ].filter(Boolean))) as string[];
    const emailTo = recipientEmails.length === 1 ? recipientEmails[0] : recipientEmails;
    const reportUsageIncrement = recipientEmails.length;

    const targetDevice = await resources.devices.info(reportData.report_device);
    const deviceName = targetDevice.name || reportData.report_device;
    const organizationDeviceId = await resolveReportOrganizationDeviceId(resources, targetDevice, device_id);
    const deviceClientName = await resolveReportClientName(resources, targetDevice, organizationDeviceId, reportData);
    const clientName = isInformedName(recipient.organizationName)
        ? String(recipient.organizationName)
        : deviceClientName;
    const organizationPlan = await getReportOrganizationPlan(resources, organizationDeviceId);

    if (!organizationPlan) {
        context.log(`No organization plan found for report limit check. organizationDeviceId=${organizationDeviceId}`);
    } else {
        context.log(`Report plan limit check: plan=${organizationPlan.id} reports_limit=${organizationPlan.reportLimit} requested=${reportUsageIncrement}`);
    }

    const planLimit = await enforcePlanLimit(resources, organizationDeviceId, "reports", organizationPlan, reportUsageIncrement, false);

    if (!planLimit.allowed) {
        await resources.devices.sendDeviceData(device_id, {
            variable: "validation",
            value: planLimit.message || "Limite de relatórios atingido para o plano da organização.",
            metadata: {
                type: "danger",
                show_markdown: true,
                ...(reportData.report_session_id ? { session_id: reportData.report_session_id } : {})
            }
        });

        return context.log(planLimit.message || "Cannot create report: organization plan limit reached");
    }

    const queryVariables = Array.from(new Set([...reportData.report_variables, "data"]));

    const rawData = await getReportDeviceData(resources, reportData.report_device, queryVariables, startDate, endDate);

    const points: ReportPoint[] = [];

    for (const item of rawData) {
        const time = new Date(item.time || item.created_at || new Date());
        for (const variable of reportData.report_variables) {
            const value = getPointValue(item, variable);
            if (value === null) continue;

            points.push({
                variable,
                label: getVariableLabel(variable),
                value,
                unit: item.unit || variableUnits[variable] || "",
                time
            });
        }
    }

    context.log(`Report data fetched: raw=${rawData.length} points=${points.length} start=${startDate.toISOString()} end=${endDate.toISOString()}`);

    const summaries = summarize(points, reportData.report_variables);
    const reportParams = {
        data: reportData,
        deviceName,
        clientName,
        startDate,
        endDate,
        points,
        summaries
    };
    let compactPdf = false;
    let html = buildReportHtml(reportParams);
    let htmlSize = Buffer.byteLength(html, "utf8");

    if (htmlSize > PDF_HTML_SAFE_LIMIT_BYTES) {
        compactPdf = true;
        html = buildReportHtml({ ...reportParams, compact: true });
        htmlSize = Buffer.byteLength(html, "utf8");
    }

    context.log(`PDF report HTML size=${htmlSize} bytes compact=${compactPdf}`);

    const safeName = (reportData.report_name || deviceName)
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-zA-Z0-9_-]+/g, "-")
        .replace(/^-|-$/g, "")
        .toLowerCase() || "relatorio";

    const fileName = `relatorio-${safeName}.pdf`;
    const csvFileName = fileName.replace(/\.pdf$/i, ".csv");
    const csvArchive = Buffer.from(buildRawCsv(points, reportData.report_variables || []), "utf8").toString("base64");
    const zipFileName = `Relatorio ${cleanFileNamePart(clientName, "Cliente")} ${cleanFileNamePart(deviceName, "Sensor")}.zip`;
    const emailReportName = reportData.report_name || deviceName;
    const emailPeriod = `${formatDate(startDate)} - ${formatDate(endDate)}`;
    let pdf = await generatePdf(token, html);

    if ((!pdf.status || !pdf.result) && !compactPdf) {
        context.log(`Retrying PDF generation with compact HTML after failure${pdf.error ? `: ${pdf.error}` : ""}`);
        compactPdf = true;
        html = buildReportHtml({ ...reportParams, compact: true });
        htmlSize = Buffer.byteLength(html, "utf8");
        context.log(`PDF compact HTML size=${htmlSize} bytes`);
        pdf = await generatePdf(token, html);
    }

    if (!pdf.status || !pdf.result) {
        return context.log(`Failed to generate PDF report${pdf.error ? `: ${pdf.error}` : ""}`);
    }

    const pdfArchive = normalizePdfArchive(pdf.result);
    if (!pdfArchive) {
        return context.log(`Invalid PDF generated. result_prefix=${String(pdf.result).slice(0, 80)}`);
    }

    const zipArchive = createZipBase64([
        { filename: fileName, archive: pdfArchive },
        { filename: csvFileName, archive: csvArchive }
    ]);
    const emailMessage = [
        `Olá${recipient.name ? `, ${recipient.name}` : ""},`,
        "",
        `O seu relatório IrriGate para ${emailReportName} chegou e já está disponível.`,
        "",
        `Para acessar o material, basta fazer o download do arquivo ZIP anexado a este email. Dentro dele estão o relatório em PDF e o arquivo CSV ${csvFileName} com todos os dados brutos do período selecionado.`,
        "",
        `Período: ${emailPeriod}`,
        "",
        "Importante: salve o arquivo em um local seguro após o download, pois o link de acesso expira em 30 dias.",
        "",
        "Atenciosamente,",
        "",
        "Equipe IrriGate",
        "+55 (41) 99782-0115",
        "Curitiba-PR"
    ].join("\n");
    const emailHtml = buildReportEmailHtml({
        recipientName: recipient.name,
        reportName: emailReportName,
        period: emailPeriod,
        csvFileName
    });

    try {
        await services.email.send({
            to: emailTo,
            from: "IrriGate",
            subject: `Relatório IrriGate - ${reportData.report_name || deviceName}`,
            message: emailMessage,
            html: emailHtml,
            attachment: {
                archive: zipArchive,
                type: "base64",
                filename: zipFileName
            }
        });
    } catch (error) {
        return context.log(`Error sending report email to ${recipientEmails.join(", ")}: ${error}`);
    }

    await resources.devices.sendDeviceData(organizationDeviceId, recipientEmails.map((email, index) => ({
        variable: "relatorios",
        value: "sent",
        metadata: {
            organization_device: organizationDeviceId,
            report_device: reportData.report_device,
            report_device_name: deviceName,
            report_variables: reportData.report_variables,
            report_start_date: startDate.toISOString(),
            report_end_date: endDate.toISOString(),
            report_send_to: email,
            report_primary_email: recipient.email,
            report_extra_email: extraEmail.email || "",
            report_recipients: recipientEmails,
            report_recipient_index: index + 1,
            report_recipients_count: reportUsageIncrement,
            report_send_to_user: recipient.userId || reportData.report_user,
            report_name: reportData.report_name || deviceName,
            points_count: points.length,
            file_name: fileName,
            csv_file_name: csvFileName,
            zip_file_name: zipFileName,
            created_at: new Date().toISOString()
        }
    })));

    if (planLimit.plan) {
        await publishPlanStatus(resources, organizationDeviceId, planLimit.plan, {
            alerts: planLimit.status?.usage.alerts || 0,
            reports: (planLimit.status?.usage.reports || 0) + reportUsageIncrement
        });
    }

    await resources.devices.sendDeviceData(device_id, {
        variable: "validation",
        value: `Relatório enviado com sucesso para ${recipientEmails.join(", ")}. Faça o download do arquivo ZIP no email recebido; dentro dele estão o PDF e o CSV.`,
        metadata: {
            type: "success",
            show_markdown: true,
            ...(reportData.report_session_id ? { session_id: reportData.report_session_id } : {})
        }
    });

    await clearReportInputFormData(resources, device_id, scope, context);

    const notificationUser = reportData.report_user || recipient.userId;
    if (notificationUser) {
        try {
            await resources.run.notificationCreate(notificationUser, {
                title: "Relatório Enviado",
                message: `O relatório ${reportData.report_name || deviceName} foi enviado para ${recipientEmails.join(", ")}.`
            });
        } catch (error) {
            context.log("Error sending report notification:", error);
        }
    }

    context.log(`Report sent successfully to ${recipientEmails.join(", ")}`);
}

export { createReport };
export default new Analysis(createReport, { token: "a-f41d9713-49ec-4223-9119-8d71092df091" });
